/* ---------- storage (KV or in-isolate memory fallback) ---------- */
const MEM = globalThis.__bmMem || (globalThis.__bmMem = new Map());
const memKV = {
  async get(k) { const r = MEM.get(k); if (!r) return null; if (r.e && r.e < Date.now()) { MEM.delete(k); return null; } return r.v; },
  async put(k, v, o) { MEM.set(k, { v: v, e: o && o.expirationTtl ? Date.now() + o.expirationTtl * 1000 : 0 }); },
  async delete(k) { MEM.delete(k); },
  async list(o) {
    const pre = (o && o.prefix) || '', keys = [];
    for (const [k, v] of MEM) { if (k.indexOf(pre) === 0) keys.push({ name: k, metadata: null }); }
    return { keys, list_complete: true };
  }
};

/* ---------- namespace router (OTP_KV_1 / OTP_KV_2, MATRIX_KV, CONFLICT_KV) ----------
   Every binding falls back to the main KV (or memory) when it is missing, so nothing can crash.
   OTP_KV_2 is an automatic backup of OTP_KV_1: reads check both (in parallel), writes go to OTP_KV_1
   and fall back to OTP_KV_2 if that write fails (for example quota exceeded), deletes clear both. */
const dualKV = (p, s) => {
  if (!s || s === p) return p;
  const safe = pr => pr.catch(() => null);
  return {
    async get(k) {
      const [a, b] = await Promise.all([safe(p.get(k)), safe(s.get(k))]);
      return a != null ? a : b;
    },
    async put(k, v, o) { try { await p.put(k, v, o); } catch (e) { await s.put(k, v, o); } },
    async delete(k) { await Promise.allSettled([p.delete(k), s.delete(k)]); },
    list: o => p.list(o)
  };
};
/* ---------- v41: Cloudflare D1 (binding name: DB) ----------
   Workers Free = 1,000 KV writes / 1,000 KV list ops / day, but D1 = 100,000 row writes / day and 5,000,000 row reads / day.
   So everything that is written often (live feeds, subscribers, push state, AI cache, the notification inbox) lives in D1.
   Without a DB binding the Worker behaves exactly as before (KV). */
let DBREADY = false;
async function dbInit(env) {
  if (DBREADY || !env.DB) return;
  const q = s => env.DB.prepare(s);
  await env.DB.batch([
    q('CREATE TABLE IF NOT EXISTS kvs (k TEXT PRIMARY KEY, v TEXT, exp INTEGER NOT NULL DEFAULT 0)'),
    q('CREATE TABLE IF NOT EXISTS subs (id TEXT PRIMARY KEY, rec TEXT NOT NULL, lat REAL, lon REAL, cur INTEGER NOT NULL DEFAULT 0, wx INTEGER NOT NULL DEFAULT 0, upd INTEGER NOT NULL DEFAULT 0)'),
    q('CREATE INDEX IF NOT EXISTS subs_wx ON subs (wx)'),
    q('CREATE INDEX IF NOT EXISTS subs_cur ON subs (cur)'),
    q('CREATE TABLE IF NOT EXISTS inbox (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, tag TEXT NOT NULL UNIQUE, pid TEXT, cat TEXT, pr INTEGER DEFAULT 3, ttl INTEGER DEFAULT 21600, ri INTEGER DEFAULT 0, t_en TEXT, t_bn TEXT, b_en TEXT, b_bn TEXT, la REAL, lo REAL, glat REAL, glon REAL, gkm REAL)'),
    q('CREATE INDEX IF NOT EXISTS inbox_pid ON inbox (pid, id)'),
    q('CREATE INDEX IF NOT EXISTS inbox_ts ON inbox (ts)')
  ]);
  /* v42: full-report columns (d_en / d_bn) for the detailed notifications */
  try {
    const cols = ((await env.DB.prepare('PRAGMA table_info(inbox)').all()).results || []).map(r => r.name);
    for (const c of ['d_en', 'd_bn']) if (cols.indexOf(c) < 0) await env.DB.prepare('ALTER TABLE inbox ADD COLUMN ' + c + ' TEXT').run();
  } catch (e) { /* column already there */ }
  DBREADY = true;
}
const d1kv = env => ({
  async get(k) { await dbInit(env); const r = await env.DB.prepare('SELECT v, exp FROM kvs WHERE k = ?1').bind(String(k)).first(); if (!r || (r.exp && r.exp < Date.now())) return null; return r.v; },
  async put(k, v, o) { await dbInit(env); const e = o && o.expirationTtl ? Date.now() + o.expirationTtl * 1000 : 0; await env.DB.prepare('INSERT INTO kvs (k, v, exp) VALUES (?1, ?2, ?3) ON CONFLICT(k) DO UPDATE SET v = ?2, exp = ?3').bind(String(k), String(v), e).run(); },
  async delete(k) { await dbInit(env); await env.DB.prepare('DELETE FROM kvs WHERE k = ?1').bind(String(k)).run(); },
  async list() { return { keys: [], list_complete: true }; }
});
/* v50: batched D1 access for the translation cache - ONE query per request instead of one per string (D1 only; without a DB binding nothing is cached, so the KV write quota is never touched) */
async function trCacheGet(env, keys) {
  const m = {}; if (!env.DB || !keys.length) return m;
  try {
    await dbInit(env); const now = Date.now();
    for (let i = 0; i < keys.length; i += 50) {
      const part = keys.slice(i, i + 50);
      const rs = await env.DB.prepare('SELECT k, v, exp FROM kvs WHERE k IN (' + part.map((_, j) => '?' + (j + 1)).join(',') + ')').bind(...part).all();
      (rs.results || []).forEach(r => { if (!r.exp || r.exp >= now) m[r.k] = r.v; });
    }
  } catch (e) { /* the cache is optional */ }
  return m;
}
async function trCachePut(env, rows) {
  if (!env.DB || !rows.length) return;
  try {
    await dbInit(env);
    for (let i = 0; i < rows.length; i += 50) await env.DB.batch(rows.slice(i, i + 50).map(r => env.DB.prepare('INSERT INTO kvs (k, v, exp) VALUES (?1, ?2, ?3) ON CONFLICT(k) DO UPDATE SET v = ?2, exp = ?3').bind(r.k, r.v, r.exp)));
  } catch (e) { /* the cache is optional */ }
}
