const kvOf = env => {
  const main = env.KV || env.OTP_KV_1 || memKV, d = env.DB ? d1kv(env) : null;
  return {
    main,
    otp: dualKV(env.OTP_KV_1 || main, env.OTP_KV_2 || null),
    matrix: env.MATRIX_KV && !d ? env.MATRIX_KV : (d || main),
    conflict: env.CONFLICT_KV && !d ? env.CONFLICT_KV : (d || main),
    cache: d || main,
    db: d
  };
};

