/* ---------- founder passkey & session tokens ---------- */
/* v51: the Worker now accepts the SAME founder passkey the website checks locally (bmLocalFounder), so a passkey the site accepts can never fail here.
   Accepted: (1) built-in SHA-256 below, (2) env.FOUNDER_KEY_SHA256 (hex), (3) env.FOUNDER_PASSKEY (plain secret). Zero-width characters are ignored. */
const ZW_RE = /[\u200B-\u200D\u2060\uFEFF]/g;
const FOUNDER_HASH = '95bd19a5117c40b74198bfb82d1ed6465b4523f066e3bc30306dfab3d071dd4e';
const isPasskey = async (env, v) => {
  const given = String(v || '').replace(ZW_RE, '').trim(); if (!given) return false;
  const h = await sha(given);
  const okList = [FOUNDER_HASH, String(env.FOUNDER_KEY_SHA256 || '').trim().toLowerCase(), env.FOUNDER_PASSKEY ? await sha(String(env.FOUNDER_PASSKEY).replace(ZW_RE, '').trim()) : ''];
  return okList.some(x => x && same(h, x));
};
const mint = async (env, salt) => { const d = 'f.' + (Date.now() + 43200000); return d + '.' + await hmac(env.ADMIN_TOKEN || salt, d); };
const validTok = async (env, salt, t) => { const m = /^(f\.(\d+))\.([\w-]+)$/.exec(String(t || '')); return !!m && +m[2] > Date.now() && same(m[3], await hmac(env.ADMIN_TOKEN || salt, m[1])); };
const mintS = async (env, salt, id) => { const d = 's.' + (await sha(id)) + '.' + (Date.now() + 2592000000); return d + '.' + await hmac(env.ADMIN_TOKEN || salt, d); };
const sessId = async (env, salt, t) => {
  t = String(t || ''); if (await validTok(env, salt, t)) return 'founder';
  const m = /^(s\.([a-f0-9]+)\.(\d+))\.([\w-]+)$/.exec(t);
  return m && +m[3] > Date.now() && same(m[4], await hmac(env.ADMIN_TOKEN || salt, m[1])) ? m[2] : '';
};
const bearer = request => (request.headers.get('authorization') || '').replace(/^Bearer\s+/i, '').trim() || (request.headers.get('x-founder-key') || '').trim();
const isFounderReq = async (env, salt, request) => {
  const t = bearer(request); if (!t) return false;
  if (env.ADMIN_TOKEN && same(t, env.ADMIN_TOKEN)) return true;
  if (await validTok(env, salt, t)) return true;
  const want = String(env.FOUNDER_KEY_SHA256 || '').trim().toLowerCase();
  return !!want && same(await sha(t), want);
};

/* ---------- device parser ---------- */
const BRANDS = [
  [/^(SM-|GT-|SCH-|SGH-)|galaxy/i, 'Samsung'], [/^RMX|realme/i, 'Realme'], [/^(CPH|PH[A-Z]M|PG[A-Z]M)|oppo/i, 'OPPO'], [/^V\d{4}|^vivo|^iQOO/i, 'vivo'],
  [/^Pixel/i, 'Google'], [/redmi|poco|xiaomi|^Mi\s|^M\d{4}[A-Z]\d|^2\d{6}[A-Z]{1,2}\d?/i, 'Xiaomi'], [/oneplus|^(LE|IN|KB|GM|HD|NE|CPH2)\d{3,4}/i, 'OnePlus'],
  [/tecno|^(KG|KH|KI|LC|LD|CK|CL|BD)\d/i, 'Tecno'], [/infinix|^X\d{3,4}[A-Z]?$/i, 'Infinix'], [/^itel/i, 'itel'], [/^moto|^XT\d{4}|motorola/i, 'Motorola'],
  [/^ASUS|^ZS\d|^AI\d{4}/i, 'ASUS'], [/nokia|^TA-\d{4}/i, 'Nokia'], [/honor/i, 'Honor'], [/huawei|^[A-Z]{3}-(L|AL|TL)\d\d/i, 'Huawei'],
  [/nothing|^A0(63|65|142)/i, 'Nothing'], [/symphony/i, 'Symphony'], [/walton/i, 'Walton'], [/lava/i, 'Lava'], [/lenovo/i, 'Lenovo'], [/sony|^(XQ|SO|SOG)-/i, 'Sony']
];
const parseDevice = (request, b) => {
  /* v30: the website sends the browser's own device info as "deviceInfo"; older clients send "device" */
  const h = request.headers, ua = h.get('user-agent') || '', cd = (b && (b.device || b.deviceInfo)) || {};
  const hint = s => String(s || '').replace(/"/g, '').trim();
  let model = hint(h.get('sec-ch-ua-model')) || hint(cd.model), brand = '', os = '', br = '', m;
  const plat = hint(h.get('sec-ch-ua-platform')), pver = hint(h.get('sec-ch-ua-platform-version'));
  if (/iPhone/.test(ua)) { brand = 'Apple'; model = model || 'iPhone'; os = 'iOS ' + ((m = /OS (\d+[_\d]*)/.exec(ua)) ? m[1].replace(/_/g, '.') : ''); }
  else if (/iPad/.test(ua)) { brand = 'Apple'; model = model || 'iPad'; os = 'iPadOS'; }
  else if (/Android/.test(ua)) {
    os = 'Android ' + ((m = /Android ([\d.]+)/.exec(ua)) ? m[1] : (pver || ''));
    if (!model && (m = /Android[^;)]*;\s*([^;)]+?)(?:\s+Build\/|\s*\)|;)/.exec(ua))) model = m[1].trim();
    if (/^K$|^Android$|^Mobile$/i.test(model)) model = '';
  }
  else if (/Windows NT/.test(ua)) { os = 'Windows ' + (pver && +pver.split('.')[0] >= 13 ? '11' : ((m = /Windows NT ([\d.]+)/.exec(ua)) ? m[1] : '')); model = model || 'PC'; }
  else if (/Macintosh|Mac OS X/.test(ua)) { brand = 'Apple'; os = 'macOS'; model = model || 'Mac'; }
  else if (/CrOS/.test(ua)) { os = 'ChromeOS'; model = model || 'Chromebook'; }
  else if (/Linux/.test(ua)) { os = 'Linux'; model = model || 'PC'; }
  if (!os && plat) os = plat + (pver ? ' ' + pver : '');
  if (!brand && model) for (const r of BRANDS) if (r[0].test(model) || r[0].test(ua)) { brand = r[1]; break; }
  if (brand && model && model.toLowerCase().indexOf(brand.toLowerCase()) === 0) model = model.slice(brand.length).trim() || model;
  br = /Edg\//.test(ua) ? 'Edge' : /OPR\/|Opera/.test(ua) ? 'Opera' : /SamsungBrowser/.test(ua) ? 'Samsung Internet' : /Firefox\//.test(ua) ? 'Firefox' : /Chrome\//.test(ua) ? 'Chrome' : /Safari\//.test(ua) ? 'Safari' : '';
  return { brand, model, os: os.trim(), browser: br, text: [[brand, model].filter(Boolean).join(' ') || 'Unknown device', os.trim(), br].filter(Boolean).join(' · ') };
};

/* ---------- telegram + telemetry ---------- */
async function tg(env, text, markup, chat) {
  if (!env.TELEGRAM_BOT_TOKEN) return { ok: false, err: 'TELEGRAM_BOT_TOKEN is not set' };
  try {
    const payload = { chat_id: chat || env.FOUNDER_CHAT_ID || FOUNDER_DEFAULT, text, parse_mode: 'HTML', disable_web_page_preview: true };
    if (markup) payload.reply_markup = markup;
    const r = await fetch('https://api.telegram.org/bot' + env.TELEGRAM_BOT_TOKEN + '/sendMessage', {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload)
    });
    const j = await r.json().catch(() => ({}));
    return { ok: !!j.ok, err: j.ok ? '' : String(j.description || r.status).slice(0, 120) };
  } catch (e) { return { ok: false, err: 'network' }; }
}
/* Founder action buttons attached to every security alert (handled by /api/telegram/webhook).
   callback_data must stay <= 64 bytes: "<action>:<ip-key>". */
const kbFor = k => ({ inline_keyboard: [
  [{ text: '🚫 Ban 24h', callback_data: 'b24:' + k }, { text: '✅ Unban', callback_data: 'unb:' + k }, { text: '🔓 Clear Lockout', callback_data: 'clr:' + k }],
  [{ text: '🔒 Block User', callback_data: 'blk:' + k }, { text: '⏱️ Custom Ban', callback_data: 'ban:' + k }, { text: '🔑 Require Approval', callback_data: 'apr:' + k }]
] });
/* v30: reads the website's "gps", "deviceInfo" and "battery" fields (older "geo"/"device" still work).
   If the visitor did not allow GPS, the approximate coordinates of the IP (from Cloudflare) are shown instead. */
const meta = (request, b) => {
  const cf = request.cf || {}, dv = parseDevice(request, b), g = (b && (b.geo || b.gps)) || {}, di = (b && (b.device || b.deviceInfo)) || {};
  const hasGps = g.lat != null && g.lon != null && isFinite(+g.lat) && isFinite(+g.lon);
  const gps = hasGps
    ? '\n🧭 GPS: <a href="https://maps.google.com/?q=' + encodeURIComponent(+g.lat + ',' + +g.lon) + '">' + esc((+g.lat).toFixed(5) + ', ' + (+g.lon).toFixed(5)) + '</a>' + (g.acc ? ' ±' + esc(Math.round(+g.acc)) + 'm' : '')
    : (cf.latitude && cf.longitude ? '\n🧭 ≈ ' + esc(cf.latitude + ', ' + cf.longitude) + ' (approx., from IP)' : '');
  const mem = di.memory || di.memGB;
  const hw = [di.platform, di.screen, di.cores && (di.cores + ' cores'), mem && (mem + 'GB')].filter(Boolean).join(' · ');
  return '\n🌐 IP: <code>' + esc(request.headers.get('cf-connecting-ip')) + '</code>\n📍 ' + esc(cf.city) + ', ' + esc(cf.region) + ', ' + esc(cf.country) + ' · AS' + esc(cf.asn) + gps +
    '\n🛰 Edge: ' + esc(cf.colo) + '\n📱 ' + esc(dv.text) + (hw ? '\n💻 ' + esc(hw) : '') + (b && b.battery ? '\n🔋 ' + esc(b.battery) : '') +
    '\n🧾 ' + esc((request.headers.get('user-agent') || '').slice(0, 90)) + '\n🕒 ' + new Date().toISOString();
};
const secAlert = async (env, kv, request, dedupe, title, extra, b) => {
  const dk = 'al:' + dedupe;
  if (await kv.get(dk)) return;
  await kv.put(dk, '1', { expirationTtl: 300 });
  await tg(env, '🚨 <b>SECURITY ALERT</b>\n' + title + (extra ? '\n' + extra : '') + meta(request, b), kbFor(key(request.headers.get('cf-connecting-ip')) || 'x'));
};

/* ---------- Turnstile hook ---------- */
async function turnstile(env, token, ip) {
  if (!env.TURNSTILE_SECRET) return true;
  if (!token) return false;
  try {
    const f = new URLSearchParams({ secret: env.TURNSTILE_SECRET, response: String(token), remoteip: ip || '' });
    const r = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', { method: 'POST', body: f });
    const j = await r.json().catch(() => ({}));
    return !!j.success;
  } catch (e) { return false; }
}

