  const n = String(to).trim();
  const ok = await post('https://api.twilio.com/2010-04-01/Accounts/' + env.TW_SID + '/Messages.json', { authorization: 'Basic ' + btoa(env.TW_SID + ':' + env.TW_TOKEN), 'content-type': 'application/x-www-form-urlencoded' },
    new URLSearchParams({ To: n.charAt(0) === '+' ? n : '+' + digits(n), From: env.TW_FROM, Body: msg }).toString());
