/* Routing:  email → Resend (→ Telegram if linked) · whatsapp → Meta → Resend · sms → Twilio → Resend · telegram → linked bot chat only.
   Resend cannot send SMS/WhatsApp, so the fallback goes to the e-mail address the visitor typed. */
async function deliver(env, kv, ch, to, code, o) {
  const msg = 'BayanMatrix verification code: ' + code + '. Valid for 5 minutes. Do not share it.', subj = 'Your BayanMatrix verification code';
  const viaMail = async () => (o.email ? await sendEmail(env, o.email, subj, msg) : '');
  try {
    if (ch === 'email') {
      const v = await sendEmail(env, to, subj, msg);
      if (v) return { via: v, fallback: false };
      return { via: o.mobile ? await sendTelegramOTP(env, kv, o.mobile, msg) : '', fallback: false };
    }
    if (ch === 'telegram') return { via: await sendTelegramOTP(env, kv, to, msg), fallback: false };
    const first = ch === 'whatsapp' ? await sendWhatsApp(env, to, code, msg) : await sendTwilioSMS(env, to, msg);
    if (first) return { via: first, fallback: false };
    const v = await viaMail();
    return { via: v, fallback: !!v };
  } catch (e) { return { via: '', fallback: false }; }
}

const parseDur = t => { const m = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/i.exec(String(t || '').replace(/\s+/g, '')); if (!m || !(m[1] || m[2] || m[3])) return 0; return ((+m[1] || 0) * 3600 + (+m[2] || 0) * 60 + (+m[3] || 0)) * 1000; };
const isBlocked = (cfg, i) => cfg.banned.indexOf(i) >= 0 || cfg.denied.indexOf(i) >= 0 || !!(cfg.tban && cfg.tban[i] > Date.now());

/* ---------- founder commands ----------
   okv = OTP namespace router (so /unlock also clears OTP lockouts in OTP_KV_1 and OTP_KV_2) */
async function command(kv, cfg, text, okv) {
  okv = okv || kv;
  const parts = String(text || '').trim().split(/\s+/), c = (parts[0] || '').split('@')[0].toLowerCase(), rest = parts.slice(1), arg = rest.join(' ');
  if (c === '/ban' || c === '/deny') {
    const k = key(rest[0]); if (!k) return 'Usage: ' + c + ' <IP/Phone>';
    const dur = c === '/ban' ? parseDur(rest[1]) : 0;
    if (dur) { cfg.tban = cfg.tban || {}; cfg.tban[k] = Date.now() + dur; await setCfg(kv, cfg); return 'ban applied: ' + k + ' for ' + rest[1]; }
    const l = c === '/ban' ? cfg.banned : cfg.denied; if (l.indexOf(k) < 0) l.push(k);
    await setCfg(kv, cfg); return c.slice(1) + ' applied: ' + k;
  }
  if (c === '/unban') { const k = key(rest[0]); cfg.banned = cfg.banned.filter(x => x !== k); cfg.denied = cfg.denied.filter(x => x !== k); if (cfg.tban) delete cfg.tban[k]; await setCfg(kv, cfg); return 'cleared: ' + k; }
  if (c === '/unlock') {
    const k = key(rest[0]); if (!k) return 'Usage: /unlock <IP/Phone/Email>';
    await lockClear(kv, 'auth:' + k); await kv.delete('af:' + k); await lockClear(kv, 'pk:' + k); await lockClear(okv, 'otpip:' + k); await lockClear(okv, 'otp:' + k); await lockClear(kv, 'adm:' + k);
    await lockClear(kv, 'ed:' + k); await lockClear(kv, 'nr:' + k); return 'lockout cleared: ' + k;
  }
  if (c === '/approve') { const k = key(rest[0]); if (!k) return 'Usage: /approve <IP/Phone>'; await kv.put('appr:' + k, 'granted', { expirationTtl: 86400 }); return 'approved: ' + k; }
  if (c === '/broadcast') { cfg.broadcast = arg; await setCfg(kv, cfg); return arg ? 'broadcast set' : 'broadcast cleared'; }
  if (c === '/message') { cfg.message = arg; await setCfg(kv, cfg); return 'denial message updated'; }
  if (c === '/msg') {
    const id = key(rest[0]), t = rest.slice(1).join(' ');
    if (!id || !t) return 'Usage: /msg <User_ID> <text>';
    await kv.put('msg:' + id, t, { expirationTtl: 3600 }); return 'queued for ' + id;
  }
  if (c === '/lockdown') { cfg.lockdown = /^(on|1|true)$/i.test(rest[0] || ''); await setCfg(kv, cfg); return 'lockdown ' + (cfg.lockdown ? 'ON' : 'OFF'); }
  if (c === '/status') return 'banned: ' + cfg.banned.length + ', denied: ' + cfg.denied.length + ', lockdown: ' + cfg.lockdown + ', broadcast: ' + (cfg.broadcast || '-');
  return 'Commands: /ban <IP/Phone> [8m13s] /deny /unban /unlock /approve <IP/Phone> | /msg <ID> <text> | /broadcast <text> | /message <text> | /lockdown on|off | /status';
}

/* ---------- tiered intruder defense ----------
   3rd wrong passcode : silent capture + Telegram alert (user is NOT locked)
   5th wrong passcode : locked 1 minute (live countdown in the UI)
   10th wrong passcode: locked 15 minutes + CRITICAL brute-force alert (every further failure re-locks 15 min) */
async function authState(kv, ipk) {
  const left = await lockLeft(kv, 'auth:' + ipk), n = +(await kv.get('af:' + ipk) || 0);
  return { ok: true, locked: left > 0, retryAfter: left, tier: left > 0 ? (n >= 10 ? 2 : 1) : 0, count: n };
}
async function authFail(env, kv, request, b, ipk, field) {
  const n = +(await kv.get('af:' + ipk) || 0) + 1;
  await kv.put('af:' + ipk, String(n), { expirationTtl: 1800 });
  let tier = 0, ttl = 0;
  if (n >= 10) { tier = 2; ttl = 900; } else if (n === 5) { tier = 1; ttl = 60; }
  if (ttl) await lockSet(kv, 'auth:' + ipk, ttl);
  if (n === 3 || n === 5 || n >= 10) {
    const d = b.device || b.deviceInfo || {}, plen = String(b.pin == null ? '' : b.pin).length;
    const head = n >= 10
      ? '🔴🚨 <b>CRITICAL — SUSPECTED BRUTE-FORCE ATTACK</b>\n⛔ ' + n + ' failed attempts · user locked for 15 minutes\n❗ <b>IMMEDIATE ATTENTION REQUIRED</b>'
      : n >= 5 ? '🟡 <b>SECURITY ALERT — ' + n + ' failed attempts</b>\n⏳ User locked for 1 minute'
      : '🚨 <b>SECURITY ALERT — 3 failed attempts</b>\n👁 Silent capture (user not locked yet)';
    await tg(env, head + '\n⚠️ Field: <b>' + esc(field) + '</b> · typed ' + plen + ' chars (value withheld)' +
      '\n👤 ' + esc(b.name) + '\n✉️ ' + esc(b.email) + '\n📱 ' + esc(b.mobile) + '\n🌍 ' + esc(b.country) + '\n🏢 ' + esc(b.organization) + '\n🗣️ ' + esc(b.language) +
      '\n💻 ' + esc([d.platform, d.screen, d.cores && (d.cores + ' cores'), (d.memory || d.memGB) && ((d.memory || d.memGB) + 'GB')].filter(Boolean).join(' · ')) + meta(request, b), kbFor(ipk));
  }
  return { ok: false, locked: !!ttl, tier, retryAfter: ttl, count: n };
}

