    title: '⚽ ' + ((hn && an) ? hn + ' vs ' + an : (ev.name || 'Match')),
    score: (st.state === 'pre' || (hs === '' && as === '')) ? '' : hs + ' - ' + as,
    status: st.state === 'in' ? ('🔴 LIVE ' + clock).trim() : (st.detail || '')
