/* CricAPI's free plan allows ~100 calls/day, so cricket has its own cache (CRIC_REFRESH_SEC, default 900 s = 96 calls/day). Lower it on a paid plan. */
async function cricketFeed(env, kv) {
  if (!env.CRIC_API_KEY) return { list: [], note: 'cricket needs CRIC_API_KEY' };
  const ttl = Math.max(60, +env.CRIC_REFRESH_SEC || 900) * 1000;
  let c = null; try { c = JSON.parse(await kv.get('cric:v1') || 'null'); } catch (e) { c = null; }
  if (c && Date.now() - c.t < ttl) return { list: c.list, note: '' };
  const cr = await jget('https://api.cricapi.com/v1/currentMatches?offset=0&apikey=' + encodeURIComponent(env.CRIC_API_KEY), 3500);
  if (cr && cr.data) {
    const list = cr.data.slice(0, 40).map(cricMatch);
    try { await kv.put('cric:v1', JSON.stringify({ t: Date.now(), list }), { expirationTtl: 86400 }); } catch (e) { /* ignore */ }
    return { list, note: '' };
  }
  return { list: c ? c.list : [], note: 'cricket feed unavailable' + (cr && cr.reason ? ': ' + String(cr.reason).slice(0, 80) : '') };
}
async function buildSports(env, kv) {
  const [fb, cr] = await Promise.all([footballFeed(), cricketFeed(env, kv)]), notes = [];
  if (!fb.length) notes.push('football feed unavailable');
  if (cr.note) notes.push(cr.note);
  const rank = m => (m.live ? 0 : m.state === 'pre' ? 1 : 2), sp = m => (m.sport === 'cricket' ? 0 : 1);
  const matches = cr.list.concat(fb).sort((a, b) => rank(a) - rank(b) || sp(a) - sp(b) || String(a.start).localeCompare(String(b.start))).slice(0, 100);
  const res = { ok: true, matches, provider: 'espn' + (env.CRIC_API_KEY ? '+cricapi' : ''), notes, updated: Date.now() };
  SP_MEM.d = res;
  try { await kv.put('sports:v2', JSON.stringify(res), { expirationTtl: 3600 }); } catch (e) { /* ignore */ }
  return res;
}
async function sportsFeed(env, kv, ctx, force) {
  let c = SP_MEM.d;
  if (!c) { try { c = JSON.parse(await kv.get('sports:v2') || 'null'); } catch (e) { c = null; } if (c) SP_MEM.d = c; }
  if (!force && c && Date.now() - c.updated < SP_FRESH) return c;
  const pr = SP_PEND || (SP_PEND = buildSports(env, kv).finally(() => { SP_PEND = null; }));
  if (!force && c && ctx) { ctx.waitUntil(pr.catch(() => {})); return c; }
  return pr;
}

