const GUARD_NOTE = 'SAFETY (moderation fallback is active for this conversation): politely refuse, in one or two sentences and in the user\'s language, any request that would give practical help with violent crime, sexual content involving minors, weapons capable of mass casualties, or methods of suicide or self-harm; for self-harm, respond with care and encourage reaching out to a trusted person or local emergency/crisis services. Answer everything else normally.';

/* v43: cross-isolate rate counter on the Cache API (shared by all isolates of one Cloudflare data centre; no KV writes, no extra billing).
   Fixed one-window buckets expire by themselves. Read-modify-write is not atomic, so under a burst it can undercount slightly - it is an abuse brake,
   not an exact meter. If the Cache API is unavailable (or put/match is a no-op on the host), it fails open and the in-memory limiter still applies. */
const cacheHit = async (k, max, ttl) => {
  try {
    const c = caches.default, win = Math.floor(Date.now() / (ttl * 1000));
    const rq = new Request('https://rl.bayanmatrix.invalid/' + encodeURIComponent(k) + '/' + win);
    const r = await c.match(rq), n = r ? (parseInt(await r.text(), 10) || 0) : 0;
    if (n >= max) return false;
    await c.put(rq, new Response(String(n + 1), { headers: { 'cache-control': 'public, max-age=' + (ttl + 5) } }));
    return true;
  } catch (e) { return true; }
};
/* v44: moderation for the image / vision modes of /api/ai (they used to run before every guard check).
   Same rules as chat: local hard patterns first (no AI call), harmless short prompts skip Llama-Guard, the verdict cache is shared with chat,
   and the Founder keeps the soft-category pass-list. Returns 'blocked', 'unavailable' (guard could not run - public users fail closed, because
   an image prompt cannot carry the safety note a chat answer gets) or null (allowed). */
const mediaGuard = async (env, prompt, founder) => {
  if (lightGuardBlocks(prompt)) return 'blocked';
  if (prompt.trim().length <= 120 && !GUARD_RISK.test(prompt)) return null; /* harmless short prompt: no Llama-Guard call */
  if (waDown(env)) return founder ? null : 'unavailable';
  try {
    const gk = 'g:' + await sha(prompt.slice(0, 4000)), gc = GUARD_MEM.get(gk);
    let gv;
    if (gc && Date.now() - gc.t < 21600000) gv = gc.v;
    else {
      const gd = await env.AI.run(M.guard, { messages: [{ role: 'user', content: prompt.slice(0, 4000) }] });
      gv = String(gd && gd.response || '');
      if (GUARD_MEM.size > 500) GUARD_MEM.clear();
      GUARD_MEM.set(gk, { v: gv, t: Date.now() });
    }
    if (/^\s*unsafe/i.test(gv)) {
      const cats = (gv.match(/S\d+/gi) || []).map(x => x.toUpperCase());
      if (!(founder && cats.length && cats.every(c => ['S5', 'S6', 'S8', 'S12', 'S13'].indexOf(c) >= 0))) return 'blocked';
    }
    return null;
  } catch (e) { if (LIMIT_RE.test(String((e && e.message) || e))) markWaLimit(); return founder ? null : 'unavailable'; }
};
const sseLine = o => enc.encode('data: ' + o + '\n\n');
const oaiToCf = resp => {
  const rd = resp.body.getReader(), dec = new TextDecoder(); let buf = '';
  return new ReadableStream({
    async pull(ctl) {
      for (;;) {
        const { done, value } = await rd.read();
        if (done) { ctl.enqueue(sseLine('[DONE]')); ctl.close(); return; }
        buf += dec.decode(value, { stream: true });
        const lines = buf.split('\n'); buf = lines.pop(); let sent = false, fin = false;
        for (let ln of lines) {
          ln = ln.trim(); if (ln.indexOf('data:') !== 0) continue;
          const d = ln.slice(5).trim(); if (d === '[DONE]') { fin = true; continue; }
          try { const t = JSON.parse(d).choices[0].delta.content; if (t) { ctl.enqueue(sseLine(JSON.stringify({ response: t }))); sent = true; } } catch (e) { /* skip */ }
        }
        if (fin) { ctl.enqueue(sseLine('[DONE]')); ctl.close(); try { rd.cancel(); } catch (e) { /* ignore */ } return; }
        if (sent) return;
      }
    },
    cancel() { try { rd.cancel(); } catch (e) { /* ignore */ } }
  });
};
/* Provider chain for chat: Gemini -> Groq -> OpenRouter (:free) -> Mistral. Returns an SSE stream or null; Workers AI is the caller's final fallback.
   Fail-over is immediate: a 429 / 5xx / timeout / network error on one provider moves to the next one in the same request, with no sleep or retry delay.
   Cool-down (only so later requests do not waste a call on a provider that just said "limit reached"): 429 -> Retry-After (clamped 5-300 s, default 60 s),
   5xx or timeout -> 20 s, 401/402/403 -> 10 min. Every cool-down check is "skip if still resting"; a provider is tried again automatically when its time is over. */
/* v50: ONE engine for every external call (chat AND translation / cron jobs). Order: Gemini -> Groq -> OpenRouter (:free) -> Mistral; when one fails the next one is tried
   at once - no sleep, no retry delay. Cool-down rules are exactly the ones above (429 -> Retry-After 5-300 s, 5xx / timeout -> 20 s, 401/402/403 -> 10 min).
   o.stream  : true -> returns the SSE stream (chat). Otherwise returns { v, via } where v = o.accept(text) (or the text itself); an answer that accept() rejects moves on to the next provider.
   o.diag    : an array that receives one short reason per failed provider ("groq 429 · ..."). Only the Founder ever sees it. Key values are never written into it. */
const extHas = env => EXT_AI.some(P => !!env[P.k]);
const extRun = async (env, msgs, maxTokens, o) => {
  o = o || {};
  const dg = o.diag, note = s => { if (dg && dg.indexOf(s) < 0) dg.push(s); };
  for (const P of EXT_AI) {
    if (!env[P.k]) { note(P.n + ' key missing'); continue; }
    const rest = (EXT_DOWN[P.n] || 0) - Date.now();
    if (rest > 0) { note(P.n + ' resting ' + Math.ceil(rest / 1000) + 's'); continue; }
    const list = String(env[P.m] || '').split(',').map(s => s.trim()).filter(Boolean);
    let all429 = true, retry = 0;
    for (const model of (list.length ? list : P.dm)) {
      let status = 0, detail = '';
      try {
        const ac = new AbortController(), tm = setTimeout(() => ac.abort(), o.stream ? 20000 : 30000);
        const bd = { model, messages: msgs, max_tokens: maxTokens, stream: !!o.stream };
        if (o.temperature != null) bd.temperature = o.temperature;
        const r = await fetch(P.u, { method: 'POST', signal: ac.signal, headers: Object.assign({ 'content-type': 'application/json', authorization: 'Bearer ' + env[P.k] }, P.n === 'openrouter' ? { 'X-Title': 'BayanMatrix' } : {}),
          body: JSON.stringify(bd) });
        status = r.status;
        if (r.ok && o.stream && r.body) { clearTimeout(tm); return oaiToCf(r); }
        if (r.ok && !o.stream) {
          let t = '';
          try { const j = await r.json(); t = String((j && j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || ''); } catch (e) { t = ''; }
          clearTimeout(tm);
          t = t.replace(/^```[a-z]*\s*|```\s*$/g, '').trim();
          const v = t ? (o.accept ? o.accept(t) : t) : null;
          if (v) return { v, via: P.n };
          detail = t ? 'answer rejected' : 'empty answer';
        } else {
          clearTimeout(tm);
          if (status === 429) retry = Math.max(retry, parseInt(r.headers.get('retry-after'), 10) || 0);
          if (dg) { /* the provider's own short error text (Founder only) tells "per-minute" from "daily" limits */
            try { const tx = await r.text(); let m = tx; try { const j = JSON.parse(tx), e0 = Array.isArray(j) ? j[0] : j; m = (e0 && e0.error && (e0.error.message || e0.error)) || tx; } catch (e) { /* plain text */ } detail = String(m).replace(/\s+/g, ' ').slice(0, 90); } catch (e) { /* ignore */ }
          } else { try { r.body && r.body.cancel(); } catch (e) { /* ignore */ } }
        }
      } catch (e) { detail = (e && e.name === 'AbortError') ? 'timeout' : 'network error'; /* timeout / network error: next model or provider */ }
      note(P.n + ' ' + (status || 'no response') + (detail ? ' · ' + detail : ''));
      if (status !== 429) all429 = false;
      if (status === 401 || status === 402 || status === 403) { EXT_DOWN[P.n] = Date.now() + 600000; break; }
      if (status === 429 && P.n !== 'openrouter') { EXT_DOWN[P.n] = Date.now() + Math.min(300, Math.max(5, retry || 60)) * 1000; break; }
      if (status === 0 || status >= 500) { EXT_DOWN[P.n] = Date.now() + 20000; break; }
    }
    /* OpenRouter: every :free model answered 429 -> the whole provider rests (single model 429s still just try the next model at once) */
    if (P.n === 'openrouter' && all429 && !(EXT_DOWN[P.n] > Date.now())) EXT_DOWN[P.n] = Date.now() + Math.min(300, Math.max(5, retry || 60)) * 1000;
  }
  return null;
};
const extChat = (env, msgs, maxTokens, diag) => extRun(env, msgs, maxTokens, { stream: true, diag });
/* v50: one-shot LLM call for the translation / cron jobs. SAME order as the chat: Gemini -> Groq -> OpenRouter -> Mistral first,
   Cloudflare Workers AI (M.fast, then M.chat) only as the very last resort - and not at all while it is known to be out of its daily allowance.
   accept(text) returns the parsed result, or null to reject an unusable answer (the next provider / model is then tried). Returns the parsed result or null.
   The external call gets 2048 extra tokens of head-room (Gemini 2.5 counts its internal thinking inside max_tokens). */
const llmAsk = async (env, system, user, chatTokens, fastTokens, temperature, accept) => {
  const msgs = [{ role: 'system', content: system }, { role: 'user', content: user }];
  const x = await extRun(env, msgs, Math.min(8192, chatTokens + 2048), { temperature, accept });
  if (x) return x.v;
  if (!env.AI || waDown(env)) return null;
  for (const [mdl, mt] of TR_ORDER(chatTokens, fastTokens)) {
    try {
      const prm = { messages: msgs, max_tokens: mt }; if (temperature != null) prm.temperature = temperature;
      const r = await env.AI.run(mdl, prm);
      const raw = r && (r.response != null ? r.response : (r.result && r.result.response));
      const t = (raw && typeof raw === 'object' ? JSON.stringify(raw) : String(raw || '')).replace(/^```[a-z]*\s*|```\s*$/g, '').trim();
      const v = t ? (accept ? accept(t) : t) : null;
      if (v) return v;
    } catch (e) { if (LIMIT_RE.test(String((e && e.message) || e))) { markWaLimit(); break; } /* try the next model */ }
  }
  return null;
};
/* copies the stream through unchanged and, when it finishes, hands the full answer text to onDone */
const tapStream = (stream, onDone) => {
  const dec = new TextDecoder(); let buf = '', text = '';
  const scan = ln => { ln = ln.trim(); if (ln.indexOf('data:') !== 0) return; const d = ln.slice(5).trim(); if (!d || d === '[DONE]') return; try { const t = JSON.parse(d).response; if (typeof t === 'string') text += t; } catch (e) { /* skip */ } };
  return stream.pipeThrough(new TransformStream({
    transform(chunk, c) { c.enqueue(chunk); buf += dec.decode(chunk, { stream: true }); const ls = buf.split('\n'); buf = ls.pop(); ls.forEach(scan); },
    flush() { if (buf) scan(buf); try { onDone(text); } catch (e) { /* ignore */ } }
  }));
};

/* ---------- model runner ---------- */
async function runModel(env, def, b) {
  const text = String(b.input || b.prompt || '').slice(0, 12000);
  const bytes = s => Uint8Array.from(atob(String(s || '').replace(/^data:[^,]*,/, '')), c => c.charCodeAt(0));
  const im = def.impl;
  if (im === M.embed) { const r = await env.AI.run(im, { text: [text] }); return { embedding: r.data && r.data[0], shape: r.shape }; }
  if (im === M.xlate) { const r = await env.AI.run(im, { text, source_lang: String(b.from || 'english'), target_lang: String(b.to || 'bengali') }); return { text: r.translated_text }; }
  if (im === M.senti) { const r = await env.AI.run(im, { text }); return { result: r }; }
  if (im === M.summ)  { const r = await env.AI.run(im, { input_text: text, max_length: 300 }); return { text: r.summary }; }
  if (im === M.tts)   { const r = await env.AI.run(im, { prompt: text, lang: String(b.lang || 'en') }); return { audio: r.audio }; }
  if (im === M.img)   { const r = await env.AI.run(im, { prompt: text.slice(0, 2000), steps: 4 }); return { image: 'data:image/jpeg;base64,' + r.image }; }
  if (im === M.stt)   { const r = await env.AI.run(im, { audio: String(b.audio || '').replace(/^data:[^,]*,/, '') }); return { text: r.text, vtt: r.vtt }; }
  if (im === M.detect){ const u = bytes(b.image); if (!u.length || u.length > 1500000) return { error: 'image_size' }; return { detections: await env.AI.run(im, { image: Array.from(u) }) }; }
  if (im === M.vision){ const u = bytes(b.image); if (!u.length || u.length > 1500000) return { error: 'image_size' }; const r = await env.AI.run(im, { messages: [{ role: 'user', content: text }], image: Array.from(u), max_tokens: 900 }); return { text: r.response }; }
  if (im === M.guard) { const r = await env.AI.run(im, { messages: [{ role: 'user', content: text }] }); return { verdict: r.response }; }
  const r = await env.AI.run(im, { messages: [{ role: 'system', content: PERSONA }, { role: 'user', content: text }], max_tokens: 1200 });
  return { text: r.response };
}

