        (w.results.bindings || []).forEach(r => { const k = codes.find(x => 'http://www.wikidata.org/entity/' + QID[x] === r.c.value); if (k) { np.c[k] = np.c[k] || {}; if (r.hl) np.c[k].head = r.hl.value; if (r.gl) np.c[k].gov = r.gl.value; } });
