  sec('Who is involved', [c.powers, c.leaders ? 'Leaders: ' + c.leaders : '']);
  sec('Countries involved — key facts', (c.sides || []).map(x => '▸ ' + (x.name || x.code) + '\nHead of state: ' + (x.head || 'n/a') + ' · Government: ' + (x.gov || 'n/a') + '\nPopulation: ' + fmtBig(x.pop) + (x.popY ? ' (' + x.popY + ')' : '') + ' · Military spending: ' + (x.mil == null ? 'n/a' : 'US$ ' + fmtBig(x.mil) + (x.milY ? ' (' + x.milY + ')' : ''))));
  sec('Latest reports, newest first', (c.items || []).slice(0, 6).map((i, k) => (k + 1) + '. ' + String(i.t).slice(0, 200) + ' — ' + i.s + ', ' + agoTxt(i.ts, now) + (i.u ? '\n   ' + i.u : '')));
