  const mx = ((await DB.prepare('SELECT MAX(id) AS m FROM inbox WHERE pid IS NULL').first()) || {}).m || 0;
  if (!mx) return { sent: 0 };
  const subs = ((await DB.prepare('SELECT id, rec, cur FROM subs WHERE cur < ?1 ORDER BY cur ASC LIMIT ?2').bind(mx, Math.max(5, +env.PUSH_SUBS_RUN || 60)).all()).results) || [];
