  const rs = ((await env.DB.prepare('SELECT id, ts, tag, pid, cat, pr, t_en, t_bn, b_en, b_bn, la, lo, glat, glon, gkm, (COALESCE(length(d_en), 0) > 0 OR COALESCE(length(d_bn), 0) > 0) AS hd FROM inbox WHERE id > ?1 AND ts > ?2 AND (pid IS NULL OR pid = ?3) ORDER BY id DESC LIMIT 200').bind(since, Date.now() - 7 * 864e5, pid || '-').all()).results) || [];
