        const founder = (await isFounderReq(env, salt, request).catch(() => false)) || (await validTok(env, salt, b.tok || b.token || b.founderToken).catch(() => false)); /* v38: verified founder session -> FOUNDER MODE. v50: the signed founder token is also accepted from the JSON body ("tok", like /api/sync and /api/model/run), not only from the Authorization header */
