        const bx = u8 => { let s = ''; for (let i = 0; i < u8.length; i += 8192) s += String.fromCharCode.apply(null, u8.subarray(i, i + 8192)); return btoa(s); };
        const ub = s => Uint8Array.from(atob(s), c => c.charCodeAt(0));
