            r.keys.forEach(k => { const m = k.metadata || {}; try { items.push({ id: decodeURIComponent(k.name.slice(pre.length)), h: m.h || '', u: m.u || 0, z: m.z || 0 }); } catch (e) { /* skip */ } });
